<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('mailing.view');
$id=max(1,(int)($_GET['id']??0));$st=db()->prepare('SELECT mc.*,u.name creator_name FROM mailing_campaigns mc LEFT JOIN users u ON u.id=mc.created_by WHERE mc.id=?');$st->execute([$id]);$campaign=$st->fetch();if(!$campaign){http_response_code(404);exit('Campaña no encontrada.');}
$st=db()->prepare('SELECT * FROM mailing_recipients WHERE campaign_id=? ORDER BY status,recipient_name,email');$st->execute([$id]);$recipients=$st->fetchAll();$counts=['pending'=>0,'sent'=>0,'failed'=>0,'skipped'=>0];foreach($recipients as$r)$counts[$r['status']]++;
$pageTitle=$campaign['name'];require __DIR__.'/includes/header.php';
?>
<section class="panel"><div class="panel-header"><div><h2><?=e($campaign['subject'])?></h2><span class="table-sub"><?=e(language_label($campaign['language']))?> · Creada por <?=e($campaign['creator_name']?:'Sistema')?> · <?=e(format_date($campaign['created_at']))?></span></div><div class="actions"><?php if(has_permission('mailing.manage')&&$campaign['status']!=='sent'):?><a class="btn btn-light" href="mailing_form.php?id=<?=$id?>">Editar</a><a class="btn btn-primary" href="mailing_send.php?id=<?=$id?>">Enviar campaña</a><?php endif;?><a class="btn btn-light" href="mailing.php">Volver</a></div></div>
<div class="panel-body"><div class="stats-grid stats-4"><div class="mini-stat"><small>PENDIENTES</small><strong><?=$counts['pending']?></strong></div><div class="mini-stat"><small>ENVIADOS</small><strong><?=$counts['sent']?></strong></div><div class="mini-stat"><small>FALLIDOS</small><strong><?=$counts['failed']?></strong></div><div class="mini-stat"><small>TOTAL</small><strong><?=count($recipients)?></strong></div></div><div class="email-preview"><div class="email-preview-brand"></div><h2><?=e($campaign['subject'])?></h2><div><?=nl2br(e($campaign['html_content']))?></div></div></div></section>
<section class="panel" style="margin-top:18px"><div class="panel-header"><h2>Destinatarios</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Nombre</th><th>Email</th><th>Estado</th><th>Detalle</th></tr></thead><tbody><?php foreach($recipients as$r):?><tr><td><?=e($r['recipient_name']?:'—')?></td><td><?=e($r['email'])?></td><td><span class="badge badge-<?=e($r['status']==='sent'?'green':($r['status']==='failed'?'red':'orange'))?>"><?=e($r['status'])?></span></td><td class="table-sub"><?=e($r['error_message']?:format_date($r['sent_at']))?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php require __DIR__.'/includes/footer.php';?>
